 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, vec4, color, smoothstep, mix, texture, time, dot, sin, fract } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const root = new THREE.Group();

  const visuals = config.intent?.visualSpec ?? config;
  const colors = visuals?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const timelines = [];
  const cleanupFns = [];

  // Apply cinematic primitives (none expected, but loop defensively)
  for (const prim of config.cinematicPrimitives ?? []) {
    const p = ctx.primitives?.[prim.name];
    if (typeof p === 'function') {
      const result = p(root, prim.params ?? {});
      if (result?.timeline) timelines.push(result.timeline);
      if (typeof result?.cleanup === 'function') cleanupFns.push(result.cleanup);
    }
  }

  // Text label
  const title = textItems.find((t) => t.role === 'headline') ?? textItems[0];
  if (title?.text) {
    const label = ctx.fontAtlas.createText(String(title.text).replace(/[^\x00-\x7F]/g, ''), {
      fontSize: title.typography?.fontSize ?? 39,
      color: colors.paper,
      align: 'center',
      maxWidthPx: 512,
      letterSpacingPx: title.typography?.letterSpacingPx ?? 0
    });
    if (label) {
      label.position.set(0, -0.04, 0.04);
      root.add(label);
    }
  }

  // Decorative textured plane
  if (config.imageUrl) {
    const atlas = visuals?.atlasRegion ?? config.atlasRegion ?? { x: 0, y: 0, w: 512, h: 320 };
    const aspect = (atlas.w ?? 512) / (atlas.h ?? 320);

    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.needsUpdate = true;

      const planeH = 0.8;
      const planeW = planeH * aspect;

      const geo = new THREE.PlaneGeometry(planeW, planeH, 1, 1);

      // Remap UVs to atlas region when texture dimensions are known
      const fullW = tex.image?.width ?? atlas.w;
      const fullH = tex.image?.height ?? atlas.h;
      const uScale = (atlas.w ?? fullW) / fullW;
      const vScale = (atlas.h ?? fullH) / fullH;
      const uOffset = (atlas.x ?? 0) / fullW;
      const vOffset = 1 - vScale - ((atlas.y ?? 0) / fullH);

      const uvAttr = geo.attributes.uv;
      for (let i = 0; i < uvAttr.count; i++) {
        const u = uvAttr.getX(i);
        const v = uvAttr.getY(i);
        uvAttr.setXY(i, uOffset + u * uScale, vOffset + v * vScale);
      }
      uvAttr.needsUpdate = true;

      const uvNode = uv();
      const vert = uvNode.y;
      const inkC = color(colors.ink);
      const surfaceC = color(colors.surface);
      const grad = mix(inkC, surfaceC, smoothstep(0.0, 1.0, vert));

      const samp = texture(tex, uvNode);
      const texRgb = samp.xyz;
      const texA = samp.w;
      const shaded = mix(grad, texRgb, texA);

      const grain = fract(
        sin(dot(uvNode, vec2(12.9898, 78.233)))
          .mul(43758.5453)
          .add(time.mul(0.05))
      )
        .sub(0.5)
        .mul(0.04);
      const final = vec4(shaded.add(vec3(grain)), 1.0);

      const mat = new MeshBasicNodeMaterial({ transparent: true });
      mat.colorNode = final;
      mat.side = THREE.DoubleSide;

      const mesh = new THREE.Mesh(geo, mat);
      mesh.position.z = 0;
      root.add(mesh);

      // Accent signal line (<=10% of frame)
      const barW = planeW * 0.7;
      const barH = 0.025;
      const barGeo = new THREE.PlaneGeometry(barW, barH);
      const barMat = new MeshBasicNodeMaterial({ color: colors.accent });
      const bar = new THREE.Mesh(barGeo, barMat);
      bar.position.set(0, planeH * 0.45, 0.01);
      root.add(bar);
    });
  }

  // Event surface — empty for this static label, but available to adapter
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    timelines.forEach((tl) => {
      if (tl?.kill) tl.kill();
    });
    gsap.killTweensOf(root);
    cleanupFns.forEach((fn) => {
      try { fn(); } catch (_) {}
    });
    root.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose());
        } else {
          obj.material.dispose();
        }
      }
    });
  };

  return root;
}
